import { site, pageHref } from '../data/site.js';
import { siteHeaderMarkup } from '../components/site-header.js';
import { siteFooterMarkup } from '../components/site-footer.js';
import { contactDialogsMarkup } from '../components/dialogs.js';

export function legalPage(kind = 'privacy') {
  const consent = kind === 'consent';
  const title = consent ? 'Согласие на обработку данных' : 'Политика конфиденциальности';
  const section = (heading, text) => '<section><h2>' + heading + '</h2><p>' + text + '</p></section>';
  const notice = '<p class="legal-notice">Тестовая версия. Это проект документа: реальные реквизиты оператора ещё не указаны. Форма не отправляет заявки и контакты на сервер. До начала реального сбора данных необходимо заполнить сведения об операторе, контакты для обращений и условия обработки.</p>';
  const operator = site.privacy.operatorName || 'Не определён в тестовой версии';
  const contact = site.privacy.email || 'Рабочий адрес для обращений ещё не указан';
  const identity = section('Кто отвечает за данные', 'Оператор: ' + operator + '. ИНН: ' + (site.privacy.inn || 'не указан') + '. Адрес: ' + (site.privacy.address || 'не указан') + '. Контакт для запросов и отзыва согласия: ' + contact + '. Демонстрационный адрес офиса и контакты на других страницах не являются реквизитами оператора.');
  const privacyContent = identity +
    section('Какие сведения вводятся', 'Имя или выбранное обращение, телефон либо имя пользователя Telegram, текст обращения и, при наличии, параметры расчёта дома: площади этажей, материал, комплектация, фундамент, комнаты, расстояние от МКАД, срок и бюджет. Не указывайте паспортные сведения, данные банковских карт, сведения о здоровье и другие чувствительные данные. Мы не запрашиваем биометрические или специальные категории данных.') +
    section('Цель и основание', 'Предполагаемая цель рабочей формы: ответить на конкретный запрос о строительстве и обсудить расчёт. Для такой обработки предусмотрено отдельное добровольное согласие. Рекламные рассылки, публикация контактов и использование данных для иных целей этим согласием не охватываются. Отказ от отметки не ограничивает просмотр сайта и использование калькулятора.') +
    section('Как работает тестовая форма', 'Введённые имя, контакт и комментарий остаются в памяти открытой страницы. Проверка формы выполняется в браузере; запрос к серверу с заявкой, отправка по почте и передача в CRM не выполняются. После успешной демонстрационной проверки поля очищаются. До этого их можно удалить вручную; перезагрузка страницы также удаляет введённые контакты. Эта версия не создаёт серверную базу заявок.') +
    section('Настройки калькулятора и технические сведения', 'Параметры дома сохраняются в sessionStorage на время вкладки и используются для восстановления расчёта и показа его в форме. Кнопка «Сброс» в форме удаляет прикреплённый расчёт и сохранённые параметры дома, сохраняя введённые имя и контакт. Контактные поля туда не записываются. Закрытие вкладки обычно удаляет эти настройки; восстановление сессии зависит от браузера. Аналитика и рекламные cookie в код сайта не подключены. При загрузке сайта хостинг получает технические сведения, включая сетевой адрес; их обработку и журналирование необходимо описать после выбора реального хостинга. При переходе на внешние карты и другие сайты действуют их собственные правила.') +
    section('Срок, передача и защита', 'В тестовой форме обращения не передаются получателям, за рубеж или обработчикам по поручению. Для рабочей версии необходимо определить реальные сроки хранения по каждой цели, получателей, инфраструктуру, размещение баз данных в РФ при сборе данных граждан РФ и меры защиты. Сроки должны быть ограничены целью и применимыми требованиями закона; до их определения реальную отправку подключать нельзя.') +
    section('Ваши права и отзыв', 'Можно запросить сведения об обработке, уточнение, блокирование или удаление данных и отозвать согласие по рабочему контакту оператора, который будет указан здесь перед запуском. Для защиты данных оператор проверяет полномочия заявителя. Запросы рассматриваются в установленные законом сроки; при наличии самостоятельного законного основания отдельные сведения могут сохраняться после отзыва. В тестовой версии для удаления введённых контактов очистите поля или перезагрузите страницу. При нарушении прав можно обратиться в Роскомнадзор или суд.') +
    section('Версия документа', 'Редакция от ' + site.privacy.version + '. При изменении целей, состава обработки или сервисов документ должен быть актуализирован. Политика доступна из каждой формы обратной связи. Отдельный <a href="' + pageHref('/consent/') + '">проект согласия</a> опубликован на собственной странице.');
  const consentContent = identity +
    section('Предмет согласия', 'Свободно и по своей воле даю указанному оператору согласие на обработку имени, телефона либо имени пользователя Telegram, текста моего обращения и приложенных параметров расчёта дома исключительно для ответа на этот запрос и обсуждения проекта строительства. Необязательный комментарий заполняется по моему выбору.') +
    section('Способ и действия', 'Для рабочей версии предполагаются сбор, запись, систематизация, хранение, уточнение, использование для связи, блокирование и удаление, с применением средств автоматизации и без них. Получатели и лица, обрабатывающие данные по поручению, должны быть указаны до запуска рабочей формы. Распространение, публикация и рекламные рассылки не разрешаются этим согласием.') +
    section('Срок и отзыв', 'Проект рабочего срока: до завершения рассмотрения запроса, но не более 90 дней с момента получения обращения, либо до отзыва согласия, если закон не требует иного. Этот срок должен быть утверждён реальным оператором перед запуском. Отзыв направляется по рабочему адресу оператора, указанному выше, с темой «Отзыв согласия». Прекращение обработки и удаление выполняются в сроки, предусмотренные законом, с учётом иных законных оснований хранения.') +
    section('Отдельное подтверждение', 'Согласие подтверждается самостоятельной отметкой без предварительного выбора. Ознакомление с политикой и согласие не объединены с согласием на рекламу или распространение. В текущей демонстрационной версии отметка проверяет интерфейс: данные не отправляются, а реальные реквизиты оператора отсутствуют. Использовать этот проект как окончательное согласие для реального сбора данных нельзя.') +
    section('Связанный документ', 'Перед подтверждением доступна <a href="' + pageHref('/privacy/') + '">политика конфиденциальности</a>. Версия проекта согласия: ' + site.privacy.version + '.');
  return siteHeaderMarkup('') + '<main class="legal-main"><a class="legal-back" href="' + pageHref('/') + '">← На главную</a><h1>' + title + '</h1>' + notice + (consent ? consentContent : privacyContent) + '<p class="legal-law">Правовая основа: <a href="https://www.consultant.ru/document/cons_doc_LAW_61801/" target="_blank" rel="noopener noreferrer">Федеральный закон № 152 «О персональных данных»</a>, в том числе статьи 5, 6, 9, 18, 18.1, с 19 по 22. Документы описывают текущий тестовый режим и требуют заполнения реальных сведений перед запуском.</p></main>' + siteFooterMarkup() + contactDialogsMarkup();
}
